  if (!text) return out({ channel: 'web', kind: 'reject_empty' });
  const sessionId = clip(body.session || body.session_id || '', 80);
  return out({ channel: 'web', kind: 'message', subject: clip(body.subject, 200),
    customer: { id: email || (sessionId ? 'web:' + sessionId : 'web:' + digitsOf(Date.now())), name: clip(body.name, 120), email }, text });
}

