    if (String(cb.message && cb.message.chat && cb.message.chat.id) !== team) return out({ channel: 'telegram', kind: 'ignore' });
    const [action, ticket] = String(cb.data || '').split(':');
    if (!['send', 'skip'].includes(action) || !ticket) return out({ channel: 'telegram', kind: 'ignore' });
    return out({ channel: 'telegram', kind: action === 'send' ? 'approve' : 'dismiss', callback: { id: cb.id, ticket, chat: cb.message.chat.id, message_id: cb.message.message_id, by: [cb.from.first_name, cb.from.last_name].filter(Boolean).join(' ') || cb.from.username || '' } });
  }
  const m = item.message;
  if (!m || !m.chat) return out({ channel: 'telegram', kind: 'ignore' });
  if (String(m.chat.id) === team) {
    // A teammate answers a customer by replying to the bot's message about the ticket.
    const quoted = m.reply_to_message && m.reply_to_message.text ? m.reply_to_message.text : '';
    const ref = /ID: (T[0-9A-Z-]+)/.exec(quoted);
    if (ref && m.text) return out({ channel: 'telegram', kind: 'team_reply', text: clip(m.text, 4000), callback: { ticket: ref[1], by: [m.from.first_name, m.from.last_name].filter(Boolean).join(' ') } });
    return out({ channel: 'telegram', kind: 'ignore' });
  }
  if (m.chat.type && m.chat.type !== 'private') return out({ channel: 'telegram', kind: 'ignore' });
  const name = [m.from && m.from.first_name, m.from && m.from.last_name].filter(Boolean).join(' ') || (m.from && m.from.username) || '';
  const customer = { id: 'tg:' + m.from.id, name, telegram_chat: String(m.chat.id) };
  if (/^\/start\b/.test(m.text || '')) return out({ channel: 'telegram', kind: 'greet', customer });
  const media = m.photo ? '[фото]' : m.voice ? '[голосовое сообщение]' : m.document ? '[файл]' : m.video ? '[видео]' : m.sticker ? '[стикер]' : '';
  const text = clip(m.text || m.caption || '', 4000);
  if (!text && !media) return out({ channel: 'telegram', kind: 'ignore' });
  return out({ channel: 'telegram', kind: 'message', customer, text: [media, text].filter(Boolean).join(' '), has_media: Boolean(media) });
}

// Email
const fromRaw = item.from && typeof item.from === 'object' ? ((item.from.value || [])[0] || {}) : item.from;
const fromText = typeof fromRaw === 'string' ? fromRaw : `${fromRaw.name || ''} <${fromRaw.address || ''}>`;
const address = emailOf((/<([^>]+)>/.exec(fromText) || [null, fromText])[1]);
const sender = fromText.replace(/<[^>]*>/, '').replace(/"/g, '').trim();
const ours = emailOf((/<([^>]+)>/.exec((cfg.email || {}).from || '') || [null, (cfg.email || {}).from || ''])[1]);
const subject = clip(item.subject, 200);
// Never answer robots: bounces, auto-replies and our own messages would start a loop.
const robot = !address || address === ours || /^(no-?reply|mailer-daemon|postmaster|bounce|notifications?)@/i.test(address)
  || /^(auto|automatic reply|автоответ|out of office|недоставлено|undeliverable|delivery status)/i.test(subject)
  || String((item.headers && (item.headers['auto-submitted'] || item.headers['Auto-Submitted'])) || 'no') !== 'no';
if (robot) return out({ channel: 'email', kind: 'ignore', subject });
const plain = item.textPlain || item.text || String(item.textHtml || item.html || '').replace(/<[^>]+>/g, ' ');
const text = clip(freshPart(plain), 4000);
if (!text) return out({ channel: 'email', kind: 'ignore', subject });
return out({ channel: 'email', kind: 'message', subject, customer: { id: address, name: clip(sender, 120), email: address }, text });

// Thread — finds the customer's open ticket, reads the FAQ, and builds the request to the model.
