      reason: String(p.needs_human_reason || '').slice(0, 200),
    };
  } catch (e) { problem = 'bad_json'; }
} else problem = input.error ? 'llm_error' : 'no_answer';
const result = ai || { category: 'other', urgency: 'normal', sentiment: 'neutral', can_answer: false, confidence: 0, answer: '', summary: '', reason: 'модель не ответила' };

// Sending without a person is the exception: every condition must hold.
const lowered = msg.text.toLowerCase();
const forbidden = (cfg.forbidden_topics || []).find((w) => w && lowered.includes(w.toLowerCase()));
const blockers = [];
if (cfg.mode !== 'auto') blockers.push('режим черновиков');
if (!result.can_answer) blockers.push(result.reason || 'нет ответа в базе знаний');
if (result.confidence < (cfg.confidence_threshold || 0.8)) blockers.push(`уверенность ${Math.round(result.confidence * 100)}%`);
if (!(cfg.auto_categories || []).includes(result.category)) blockers.push(`категория ${result.category}`);
if (['negative', 'angry'].includes(result.sentiment)) blockers.push('клиент недоволен');
if (result.urgency === 'high') blockers.push('срочно');
if (forbidden) blockers.push(`тема «${forbidden}»`);
if (msg.has_media) blockers.push('есть вложение');
const autoSend = blockers.length === 0;
const status = autoSend ? 'answered' : result.can_answer ? 'draft_ready' : 'new';

const line = `${localText(now)} · клиент: ${msg.text.replace(/\n+/g, ' ').slice(0, 300)}`;
const reply = autoSend ? `\n${localText(now)} · бот: ${result.answer.replace(/\n+/g, ' ').slice(0, 300)}` : '';
const base = ctx.existing || { id: ctx.id, created_at: iso, channel: msg.channel, customer: msg.customer.id, name: msg.customer.name || '', email: msg.customer.email || '',
  telegram_chat: msg.customer.telegram_chat || '', subject: msg.subject || '', reminded_level: '0', assignee: '', first_response_at: '', history: '' };
const row = Object.assign({}, base, {
  updated_at: iso, category: result.category, urgency: result.urgency, sentiment: result.sentiment, status,
  summary: result.summary || base.summary || '', last_message: msg.text.slice(0, 1000), draft: result.can_answer ? result.answer : '',
  history: `${base.history ? base.history + '\n' : ''}${line}${reply}`.slice(-4000), reminded_level: '0',
  kb_answer: result.can_answer ? 'yes' : 'no',
});
if (autoSend && !row.first_response_at) row.first_response_at = iso;
const values = [TCOLS.map((c) => String(row[c] || ''))];
const http = ctx.existing
  ? { method: 'PUT', url: sheetUrl(encodeURIComponent(rowRange(ctx.sheet_row))) + '?valueInputOption=RAW', body: { values } }
  : { method: 'POST', url: sheetUrl(encodeURIComponent(ticketRange()) + ':append') + '?valueInputOption=RAW&insertDataOption=INSERT_ROWS', body: { values: ctx.has_header ? values : [TCOLS, ...values] } };

const label = { low: 'низкая', normal: 'обычная', high: 'высокая' }[result.urgency];
const mood = { positive: 'доволен', neutral: '', negative: 'недоволен', angry: 'раздражён' }[result.sentiment];
const who = [msg.customer.name, msg.customer.email || (msg.customer.telegram_chat ? 'Telegram' : '')].filter(Boolean).join(', ') || 'без имени';
const team = [
  `${autoSend ? 'Отвечено ботом' : ctx.existing ? 'Новое сообщение в обращении' : 'Новое обращение'} · ${msg.channel} · срочность: ${label}${mood ? ' · ' + mood : ''}`,
  `От: ${who}`,
  msg.subject ? `Тема: ${msg.subject}` : '',
  `Сообщение: ${msg.text.slice(0, 1200)}`,
  `Категория: ${result.category}${result.summary ? ' · ' + result.summary : ''}`,
  autoSend ? `Ответ: ${result.answer.slice(0, 1500)}` : result.can_answer ? `Черновик ответа:\n${result.answer.slice(0, 1500)}` : 'В базе знаний ответа нет — ответьте сами: ответом на это сообщение.',
  !autoSend ? `Почему не отправлено: ${blockers.join('; ')}` : '',
  problem ? `Модель: ${problem}` : '',
  `ID: ${ctx.id}`,
].filter(Boolean).join('\n');

const ack = (cfg.web || {}).ack || 'Спасибо! Мы получили ваше сообщение и ответим в ближайшее время.';
return [{ json: {
  id: ctx.id, channel: msg.channel, auto_send: autoSend, status, blockers, ai_problem: problem, category: result.category,
  http, team_chat: cfg.team_chat_id, team_text: team, show_send_button: !autoSend && result.can_answer,
  reply_text: autoSend ? result.answer : '', reply_email: msg.customer.email || '', reply_subject: (msg.subject ? (/^re:/i.test(msg.subject) ? msg.subject : 'Re: ' + msg.subject) : ((cfg.email || {}).default_subject || 'Ответ службы поддержки')),
  reply_chat: msg.customer.telegram_chat || '', web_response: { ok: true, answer: autoSend ? result.answer : '', message: autoSend ? '' : ack, ticket: ctx.id },
} }];

// Act on Ticket — a teammate pressed "Send", "We will answer", or replied to the bot in the team chat.
const cfg = $('Config').first().json;
// ---- shared helpers ----
const MIN = 60000;
const nowMs = () => (cfg.now_override ? Date.parse(cfg.now_override) : Date.now());
const digitsOf = (value) => String(value || '').replace(/[^\d]/g, '');
// Phones are stored in one international form, so the same person is recognised however they typed it.
function phoneOf(value) {
  const rules = cfg.phone || {};
  let d = digitsOf(value);
  if (d.startsWith('00')) d = d.slice(2);
  else if (rules.national_prefix && rules.country_code && d.startsWith(rules.national_prefix) && !d.startsWith(rules.country_code)) {
    d = rules.country_code + d.slice(rules.national_prefix.length);
  }
  return d.length >= 9 && d.length <= 15 ? '+' + d : '';
}
function emailOf(value) {
  const e = String(value || '').trim().toLowerCase();
  return /^[^\s@<>()",;]+@[^\s@<>()",;]+\.[a-z]{2,}$/.test(e) ? e : '';
}
const localText = (ms) => new Intl.DateTimeFormat(cfg.locale || 'ru-RU', {
  timeZone: cfg.timezone, day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit',
}).format(new Date(ms));
function localParts(ms) {
  const parts = {};
  for (const p of new Intl.DateTimeFormat('en-GB', { timeZone: cfg.timezone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', weekday: 'short' }).formatToParts(new Date(ms))) parts[p.type] = p.value;
  return { date: `${parts.year}-${parts.month}-${parts.day}`, hour: Number(parts.hour), minute: Number(parts.minute), weekday: parts.weekday.toLowerCase().slice(0, 3) };
}
const sheetUrl = (path) => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values/${path}`;
const quoteSheet = (name) => "'" + String(name).replace(/'/g, "''") + "'";
// Tickets sheet columns. The sheet may start empty: the header is written with the first ticket.
const TCOLS = ['id', 'created_at', 'updated_at', 'channel', 'customer', 'name', 'email', 'telegram_chat', 'subject', 'category', 'urgency', 'sentiment',
  'status', 'summary', 'last_message', 'draft', 'history', 'first_response_at', 'reminded_level', 'assignee', 'kb_answer'];
const colLetter = (index) => { let s = ''; let n = index + 1; while (n) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; };
const TLAST = colLetter(TCOLS.length - 1);
const ticketRange = () => `${quoteSheet(cfg.tickets_sheet)}!A1:${TLAST}`;
const rowRange = (row) => `${quoteSheet(cfg.tickets_sheet)}!A${row}:${TLAST}${row}`;
const batchGetUrl = () => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values:batchGet?ranges=${encodeURIComponent(ticketRange())}&ranges=${encodeURIComponent(`${quoteSheet(cfg.faq_sheet)}!A1:B`)}`;
function tableOf(values) {
  const rows = values || [];
  const header = rows.length && rows[0][0] === 'id';
  return { header, rows: header ? rows.slice(1) : [] };
}
const cell = (row, c) => row[TCOLS.indexOf(c)] || '';
const rowObject = (row) => Object.fromEntries(TCOLS.map((c) => [c, cell(row, c)]));
const msg = $('Normalize').first().json;
const tickets = tableOf($input.first().json.values);
const now = nowMs();
const iso = new Date(now).toISOString();
const ticketId = msg.callback.ticket;
const index = tickets.rows.findIndex((r) => cell(r, 'id') === ticketId);
const done = (note) => [{ json: { found: index >= 0, deliver: false, write: false, note, callback_id: msg.callback.id || '', team_chat: cfg.team_chat_id, message_id: msg.callback.message_id || '' } }];
if (index < 0) return done('Обращение не найдено в таблице');
const row = rowObject(tickets.rows[index]);
const sheetRow = index + (tickets.header ? 2 : 1);

if (msg.kind === 'dismiss') {
  row.status = 'new'; row.updated_at = iso; row.draft = '';
  return [{ json: { found: true, deliver: false, write: true, note: `Черновик отклонён${msg.callback.by ? ': ' + msg.callback.by : ''}. Ответьте клиенту сами.`,
    http: { method: 'PUT', url: sheetUrl(encodeURIComponent(rowRange(sheetRow))) + '?valueInputOption=RAW', body: { values: [TCOLS.map((c) => String(row[c] || ''))] } },
    callback_id: msg.callback.id, team_chat: cfg.team_chat_id, message_id: msg.callback.message_id } }];
}
if (['answered', 'closed'].includes(row.status) && msg.kind === 'approve') return done('Это обращение уже отвечено');

const text = msg.kind === 'approve' ? row.draft : msg.text;
if (!text) return done('Черновика нет — ответьте сами ответом на сообщение бота');
const who = msg.callback.by || 'команда';
row.status = 'answered'; row.updated_at = iso; row.draft = '';
if (!row.first_response_at) row.first_response_at = iso;
if (!row.assignee) row.assignee = who;
row.history = `${row.history ? row.history + '\n' : ''}${localText(now)} · ${who}: ${text.replace(/\n+/g, ' ').slice(0, 300)}`.slice(-4000);
const subject = row.subject ? (/^re:/i.test(row.subject) ? row.subject : 'Re: ' + row.subject) : ((cfg.email || {}).default_subject || 'Ответ службы поддержки');
// Answer where the customer can read it: Telegram if they wrote there, otherwise email.
const via = row.telegram_chat ? 'telegram' : row.email ? 'email' : '';
if (!via) return done('У обращения нет ни почты, ни Telegram — ответить некуда');
return [{ json: {
  found: true, deliver: true, write: true, via, reply_text: text, reply_email: row.email, reply_subject: subject, reply_chat: row.telegram_chat,
  note: `Отправлено клиенту (${who})`,
  http: { method: 'PUT', url: sheetUrl(encodeURIComponent(rowRange(sheetRow))) + '?valueInputOption=RAW', body: { values: [TCOLS.map((c) => String(row[c] || ''))] } },
  callback_id: msg.callback.id || '', team_chat: cfg.team_chat_id, message_id: msg.callback.message_id || '',
} }];

// Ticket Not Saved — the sheet is unavailable. The message goes to the team in full so nobody is left unanswered.
let msg = {};
try { msg = $('Normalize').first().json; } catch (e) {}
const error = $input.first().json.error || $input.first().json;
const c = msg.customer || {};
return [{ json: { text: ['Обращение не записано в таблицу — ответьте вручную', `Канал: ${msg.channel || '—'}`, `От: ${[c.name, c.email, c.telegram_chat ? 'Telegram ' + c.telegram_chat : ''].filter(Boolean).join(', ') || '—'}`,
  `Сообщение: ${(msg.text || '').slice(0, 1200)}`, `Ошибка: ${JSON.stringify(error).slice(0, 300)}`].join('\n') } }];
